<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import type { Context, Role, Scenario } from './dashboard';
import { tenantOptions, productOptions } from './catalog';
import { devices, type Command, type Device, type DeviceImportPreview, type DeviceInput, type DeviceListQuery, type DeviceShadow, type DeviceStatus, type TelemetryPoint } from './devices';
import { parseDeviceCsv } from './device-import';
import { utcMinuteToIso } from './device-filter-time';
import { defaultCustomFrom, defaultCustomTo, telemetryWindow } from './telemetry-range';
import type { ThingModelItem } from './products';
import { rules, type RuleExecution } from './rules';
import { deviceEvents, type DeviceAlarm, type DeviceMessage } from './device-events';
import { ota, type OtaExecution, type OtaTaskStatus } from './ota';
import { tenants } from './tenants';
import './dashboard.css';
import './products.css';
import './devices.css';

type Tab = 'overview' | 'realtime' | 'shadow' | 'telemetry' | 'messages' | 'alarms' | 'location' | 'rules' | 'ota' | 'commands';
type TelemetryView = { points: TelemetryPoint[]; metrics: { id: string; unit: string }[]; missing: { from: string; to: string }[]; noData: boolean; updatedAt: string };
const statuses: Record<DeviceStatus, string> = { unactivated: '未激活', online: '在线', offline: '离线', fault: '故障', maintenance: '维护' };
const regions: Record<string, string> = { AS: '亚洲', EU: '欧洲', NA: '北美洲', SA: '南美洲', AF: '非洲', OC: '大洋洲' };
const tabNames: Record<Tab, string> = { overview: '概览', realtime: '实时属性', shadow: '设备影子', telemetry: '时序数据', messages: '消息', alarms: '告警', location: '位置', rules: '规则执行', ota: 'OTA 历史', commands: '命令记录' };
const publishedProducts = productOptions().filter(item => item.status === 'published');
const productNames: Record<string, string> = Object.fromEntries(publishedProducts.map(item => [item.id, item.name]));
const tenantNames = tenantOptions();
const firstProduct = (tenantId: string) => publishedProducts.find(item => item.tenantId === tenantId)?.id ?? '';
const baseQuery = (): DeviceListQuery => ({ tenantId: new URLSearchParams(location.search).get('tenant') || localStorage.getItem('iot-atlas-current-tenant-v1') || 'all', seed: 42, page: 1, pageSize: 10, sortBy: 'lastActiveAt', sortDirection: 'desc' });
const role = ref<Role>('platformAdmin'), scenario = ref<Scenario>('normal');
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark');
const media = matchMedia('(prefers-color-scheme: dark)');
const systemDark = ref(media.matches);
const updateSystem = () => { systemDark.value = media.matches; };
media.addEventListener('change', updateSystem);
const dark = computed(() => themeChoice.value === 'dark' || (themeChoice.value === 'system' && systemDark.value));
watch([dark, themeChoice], () => { document.documentElement.dataset.theme = dark.value ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
const draft = ref(baseQuery()), query = ref(baseQuery()), rows = ref<Device[]>([]), total = ref(0), loading = ref(false);
const selected = ref<string | null>(new URLSearchParams(location.search).get('device')), detail = ref<Device | null>(null), tab = ref<Tab>('overview');
const selectedRows = ref<string[]>([]), showRegion = ref(true), showLastActive = ref(true);
const message = ref(''), reload = ref(0), nameDraft = ref(''), tagsDraft = ref('');
const creating = ref(false), createError = ref(''), capacityNote = ref('');
let capacityRequest = 0;
const createInput = ref<DeviceInput>({ tenantId: 'ten_202609_001', productId: 'prod_as_001', name: '', region: 'AS', countryCode: 'CN', location: null, tags: [] });
const importing = ref(false), importTenant = ref('ten_202609_001'), importProduct = ref('prod_as_001'), importRows = ref<DeviceInput[]>([]), importPreview = ref<DeviceImportPreview | null>(null), importError = ref('');
const deletePending = ref<string[]>([]), deleteError = ref('');
const entryDialogOpen = computed(() => creating.value || importing.value || deletePending.value.length > 0);
let entryTrigger: HTMLElement | null = null;
let entryOverflow = '';
watch(entryDialogOpen, async open => {
  if (open) { entryTrigger = document.activeElement instanceof HTMLElement ? document.activeElement : null; entryOverflow = document.documentElement.style.overflow; document.documentElement.style.overflow = 'hidden'; }
  else document.documentElement.style.overflow = entryOverflow;
  await nextTick();
  if (open) document.querySelector<HTMLElement>('.device-entry-dialog[role="dialog"]')?.focus();
  else { if (entryTrigger?.isConnected) entryTrigger.focus(); entryTrigger = null; }
}, { flush: 'post' });
const onEntryKeydown = (event: KeyboardEvent) => {
  if (!entryDialogOpen.value) return;
  const dialog = document.querySelector<HTMLElement>('.device-entry-dialog[role="dialog"]');
  if (!dialog) return;
  if (event.key === 'Escape') { event.preventDefault(); creating.value = false; importing.value = false; deletePending.value = []; return; }
  if (event.key !== 'Tab') return;
  const controls = Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled])'));
  if (!controls.length) return;
  const first = controls[0], last = controls[controls.length - 1];
  if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && (document.activeElement === last || document.activeElement === dialog)) { event.preventDefault(); first.focus(); }
};
window.addEventListener('keydown', onEntryKeydown);
onBeforeUnmount(() => window.removeEventListener('keydown', onEntryKeydown));
onBeforeUnmount(() => { if (entryDialogOpen.value) document.documentElement.style.overflow = entryOverflow; });
const metrics = ref<string[]>([]), range = ref(1), granularity = ref<'minute' | 'hour' | 'day'>('hour'), zoom = ref(false), live = ref(false);
const customFrom = ref(defaultCustomFrom), customTo = ref(defaultCustomTo);
const telemetry = ref<TelemetryView | null>(null), telemetryError = ref('');
const shadow = ref<DeviceShadow | null>(null), shadowError = ref('');
const capabilities = ref<ThingModelItem[]>([]), commandItem = ref(''), commandValue = ref(''), commandPreview = ref(false), commandError = ref(''), history = ref<Command[]>([]);
let commandTrigger: HTMLElement | null = null;
let commandOverflow = '';
watch(commandPreview, async (open) => {
  if (open) { commandTrigger = document.activeElement instanceof HTMLElement ? document.activeElement : null; commandOverflow = document.documentElement.style.overflow; document.documentElement.style.overflow = 'hidden'; }
  else document.documentElement.style.overflow = commandOverflow;
  await nextTick();
  if (open) document.querySelector<HTMLElement>('.device-control-sheet[role="dialog"]')?.focus();
  else if (commandTrigger?.isConnected) { commandTrigger.focus(); commandTrigger = null; }
  else { document.querySelector<HTMLElement>('[role="tab"][aria-selected="true"]')?.focus(); commandTrigger = null; }
}, { flush: 'post' });
onBeforeUnmount(() => { if (commandPreview.value) document.documentElement.style.overflow = commandOverflow; });
const onCommandKeydown = (event: KeyboardEvent) => {
  if (!commandPreview.value) return;
  const dialog = document.querySelector<HTMLElement>('.device-control-sheet[role="dialog"]');
  if (!dialog) return;
  if (event.key === 'Escape') { event.preventDefault(); commandPreview.value = false; return; }
  if (event.key !== 'Tab') return;
  const buttons = Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled])'));
  if (!buttons.length) return;
  const first = buttons[0], last = buttons[buttons.length - 1];
  if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && (document.activeElement === last || document.activeElement === dialog)) { event.preventDefault(); first.focus(); }
};
window.addEventListener('keydown', onCommandKeydown);
onBeforeUnmount(() => window.removeEventListener('keydown', onCommandKeydown));
const ruleLogs = ref<RuleExecution[]>([]), ruleLogError = ref('');
const rawMessages = ref<DeviceMessage[]>([]), alarms = ref<DeviceAlarm[]>([]), eventError = ref('');
const otaHistory = ref<{ taskId: string; taskStatus: OtaTaskStatus; execution: OtaExecution }[]>([]), otaError = ref('');
const context = (): Context => ({ actorId: 'usr_202609_001', role: role.value, tenantId: role.value === 'platformAdmin' ? 'all' : 'ten_202609_001', seed: 42, scenario: scenario.value });
const chosenCapability = computed(() => capabilities.value.find(item => item.id === commandItem.value));
const parsedCommandValue = computed(() => chosenCapability.value?.dataType === 'int' || chosenCapability.value?.dataType === 'float' ? Number(commandValue.value) : chosenCapability.value?.dataType === 'bool' ? commandValue.value === 'true' : commandValue.value);
const visiblePoints = computed(() => telemetry.value?.points ?? []);
const chips = computed(() => Object.entries({ 产品: query.value.productId ? productNames[query.value.productId] : '', 状态: query.value.status ? statuses[query.value.status] : '', 地域: query.value.region ? regions[query.value.region] : '', 标签: query.value.tag ?? '', 最后活跃: query.value.lastActiveFrom?.slice(0, 16) ?? '', 关键词: query.value.keyword ?? '' }).filter(([, value]) => value));
let listRequest = 0, detailRequest = 0, telemetryRequest = 0;
let commandTimer: ReturnType<typeof setInterval> | undefined, shadowTimer: ReturnType<typeof setInterval> | undefined, stopLive: (() => void) | undefined;
async function loadList() { const request = ++listRequest; loading.value = true; const result = await devices.list(context(), query.value); if (request !== listRequest) return; if ('error' in result) { message.value = result.error.message; rows.value = []; total.value = 0; } else { rows.value = result.data.items; total.value = result.data.total; message.value = ''; } loading.value = false; }
async function loadDetail() { if (!selected.value) return; const request = ++detailRequest; const id = selected.value; const [result, writable] = await Promise.all([devices.get(context(), id), devices.writableItems(context(), id)]); if (request !== detailRequest) return; if ('error' in result) { message.value = result.error.message; detail.value = null; return; } detail.value = result.data; nameDraft.value = result.data.name; tagsDraft.value = result.data.tags.join(','); metrics.value = Object.keys(result.data.attributes).slice(0, 2); tab.value = 'overview'; if ('data' in writable) { capabilities.value = writable.data; commandItem.value = writable.data[0]?.id ?? ''; } }
async function loadTelemetry() { if (!detail.value || tab.value !== 'telemetry' || !metrics.value.length) return; const request = ++telemetryRequest; const window = telemetryWindow(range.value, customFrom.value, customTo.value); if (!window.ok) { telemetryError.value = window.error; telemetry.value = null; return; } const from = zoom.value ? new Date((Date.parse(window.from) + Date.parse(window.to)) / 2).toISOString() : window.from; telemetry.value = null; const result = await devices.queryTelemetry(context(), { deviceId: detail.value.id, from, to: window.to, metrics: metrics.value, granularity: granularity.value, seed: 42 }); if (request !== telemetryRequest) return; if ('error' in result) { telemetryError.value = result.error.message; telemetry.value = null; } else { telemetryError.value = ''; telemetry.value = result.data; } }
async function loadCommands() { if (!detail.value || tab.value !== 'commands') return; const result = await devices.commandHistory(context(), detail.value.id); if ('data' in result) history.value = result.data; }
async function loadShadow() { if (!detail.value || tab.value !== 'shadow') return; const id = detail.value.id; const result = await devices.getShadow(context(), id); if (detail.value?.id !== id || tab.value !== 'shadow') return; if ('error' in result) { shadowError.value = result.error.message; shadow.value = null; } else { shadowError.value = ''; shadow.value = result.data; } }
async function loadRuleLogs() { if (!detail.value || tab.value !== 'rules') return; const result = await rules.logsFor(context(), { tenantId: detail.value.tenantId, deviceId: detail.value.id, page: 1, pageSize: 20, seed: 42 }); if ('error' in result) { ruleLogError.value = result.error.message; ruleLogs.value = []; } else { ruleLogError.value = ''; ruleLogs.value = result.data.items; } }
async function loadDeviceEvents() { if (!detail.value || !['messages', 'alarms'].includes(tab.value)) return; const current = detail.value, currentTab = tab.value; const result = currentTab === 'messages' ? await deviceEvents.listMessages(context(), current.id) : await deviceEvents.listAlarms(context(), current.id); if (detail.value?.id !== current.id || tab.value !== currentTab) return; if ('error' in result) { eventError.value = result.error.message; if (currentTab === 'messages') rawMessages.value = []; else alarms.value = []; } else { eventError.value = ''; if (currentTab === 'messages') rawMessages.value = result.data as DeviceMessage[]; else alarms.value = result.data as DeviceAlarm[]; } }
async function acknowledgeAlarm(id: string) { if (!detail.value) return; const result = await deviceEvents.acknowledge(context(), detail.value.id, id); if ('error' in result) eventError.value = result.error.message; else { eventError.value = ''; alarms.value = alarms.value.map(item => item.id === id ? result.data : item); } }
async function loadOtaHistory() { if (!detail.value || tab.value !== 'ota') return; const result = await ota.historyForDevice(context(), detail.value.id); if ('error' in result) { otaError.value = result.error.message; otaHistory.value = []; } else { otaError.value = ''; otaHistory.value = result.data; } }
watch([query, role, scenario, reload], loadList, { immediate: true });
watch([selected, role, scenario, reload], loadDetail, { immediate: true });
watch([detail, tab, role, scenario, reload], loadRuleLogs);
watch([detail, tab, role, scenario, reload], loadDeviceEvents);
watch([detail, tab, role, scenario, reload], loadOtaHistory);
watch([detail, tab, metrics, range, customFrom, customTo, granularity, zoom, role, scenario, reload], loadTelemetry);
watch([detail, tab], () => { if (commandTimer) clearInterval(commandTimer); if (tab.value === 'commands') { void loadCommands(); commandTimer = setInterval(() => void loadCommands(), 700); } });
watch([detail, tab, role, scenario], () => { if (shadowTimer) clearInterval(shadowTimer); if (tab.value === 'shadow') { void loadShadow(); shadowTimer = setInterval(() => void loadShadow(), 700); } });
watch(tab, async value => { if (value !== 'realtime' || !selected.value) return; const id = selected.value; const result = await devices.get(context(), id); if (tab.value === 'realtime' && selected.value === id && 'data' in result) detail.value = result.data; });
watch([live, tab, granularity, metrics, detail, role, scenario], () => {
  stopLive?.(); stopLive = undefined;
  if (!live.value || tab.value !== 'telemetry' || !detail.value || !metrics.value.length) return;
  stopLive = devices.subscribeTelemetry(context(), detail.value.id, metrics.value, granularity.value, event => {
    if ('error' in event) { telemetryError.value = event.error.message; return; }
    void deviceEvents.recordTelemetry(context(), detail.value!.id, event.data).then(result => { if ('error' in result) telemetryError.value = `原始消息未保存：${result.error.message}`; });
    void devices.applyTelemetry(context(), detail.value!.id, event.data);
    if (!telemetry.value) return;
    const current = telemetry.value;
    telemetry.value = { ...current, points: [...current.points, ...event.data], noData: current.noData && event.data.every(point => point.value === null),
      missing: event.data[0]?.value === null ? [...current.missing, { from: event.data[0].timestamp, to: event.data[0].timestamp }] : current.missing,
      updatedAt: event.data[0]?.timestamp ?? current.updatedAt };
  });
});
onBeforeUnmount(() => { media.removeEventListener('change', updateSystem); if (commandTimer) clearInterval(commandTimer); if (shadowTimer) clearInterval(shadowTimer); stopLive?.(); });
function apply() { query.value = { ...draft.value, page: 1 }; selectedRows.value = []; }
function reset() { const next = { ...baseQuery(), tenantId: role.value === 'platformAdmin' ? baseQuery().tenantId : 'ten_202609_001' }; draft.value = next; query.value = next; selectedRows.value = []; }
function changeRole(next: Role) { role.value = next; const tenantId = next === 'platformAdmin' ? 'all' : 'ten_202609_001'; draft.value = { ...draft.value, tenantId, page: 1 }; query.value = { ...query.value, tenantId, page: 1 }; selected.value = null; detail.value = null; commandPreview.value = false; }
function removeChip(key: string) { const field = ({ 产品: 'productId', 状态: 'status', 地域: 'region', 标签: 'tag', 最后活跃: 'lastActiveFrom', 关键词: 'keyword' } as Record<string, keyof DeviceListQuery>)[key]; const next = { ...query.value, [field]: undefined, page: 1 }; query.value = next; draft.value = next; }
function sort(by: DeviceListQuery['sortBy']) { query.value = { ...query.value, sortBy: by, sortDirection: query.value.sortBy === by && query.value.sortDirection === 'asc' ? 'desc' : 'asc' }; }
function selectPage(checked: boolean) { selectedRows.value = checked ? [...new Set([...selectedRows.value, ...rows.value.map(item => item.id)])] : selectedRows.value.filter(id => !rows.value.some(item => item.id === id)); }
function selectRow(id: string, checked: boolean) { selectedRows.value = checked ? [...selectedRows.value, id] : selectedRows.value.filter(item => item !== id); }
function download(name: string, content: string) { const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([content], { type: 'text/csv;charset=utf-8' })); link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 0); }
function cell(value: unknown) { return `"${String(value ?? '').replaceAll('"', '""')}"`; }
async function exportRows() { const results = await Promise.all(selectedRows.value.map(id => devices.get(context(), id))); const failure = results.find(result => 'error' in result); if (failure && 'error' in failure) { message.value = `设备导出失败：${failure.error.message}`; return; } const selectedDevices = results.flatMap(result => 'data' in result ? [result.data] : []); download('devices.csv', ['id,name,status,product,region', ...selectedDevices.map(item => [item.id, item.name, item.status, item.productId, item.region].map(cell).join(','))].join('\n')); }
function exportTelemetry() { if (telemetry.value) download('telemetry.csv', ['timestamp,metric,value,unit,quality', ...telemetry.value.points.map(point => [point.timestamp, point.metric, point.value, point.unit, point.quality].map(cell).join(','))].join('\n')); }
async function saveMetadata() { if (!detail.value) return; const result = await devices.updateMetadata(context(), detail.value.id, { name: nameDraft.value, tags: tagsDraft.value.split(',').map(value => value.trim()).filter(Boolean) }, detail.value.version); if ('error' in result) message.value = result.error.message; else { detail.value = result.data; reload.value++; message.value = '设备信息已保存'; } }
async function loadDeviceCapacity(tenantId: string) { const request = ++capacityRequest; capacityNote.value = '正在查询设备配额…'; const result = await tenants.checkCapacity(context(), tenantId, 'devices'); if (request !== capacityRequest) return; capacityNote.value = 'error' in result ? result.error.message : `设备配额已用 ${result.data.used}/${result.data.limit}${(result.data.used + 1) / result.data.limit * 100 >= result.data.warningAt ? `；登记后达到 ${result.data.warningAt}% 预警阈值` : ''}`; }
function newDevice() { const tenantId = query.value.tenantId === 'all' ? 'ten_202609_001' : query.value.tenantId; createInput.value = { tenantId, productId: firstProduct(tenantId), name: '', region: 'AS', countryCode: tenantId === 'ten_202609_002' ? 'JP' : 'CN', location: null, tags: [] }; createError.value = ''; creating.value = true; void loadDeviceCapacity(tenantId); }
function setCreateTenant(tenantId: string) { createInput.value = { ...createInput.value, tenantId, productId: firstProduct(tenantId) }; void loadDeviceCapacity(tenantId); }
async function createDevice() { const result = await devices.create(context(), JSON.parse(JSON.stringify(createInput.value)) as DeviceInput); if ('error' in result) { createError.value = result.error.message; return; } creating.value = false; selected.value = result.data.id; reload.value++; message.value = `设备 ${result.data.id} 已登记为未激活`; }
function openImport() { const tenantId = query.value.tenantId === 'all' ? 'ten_202609_001' : query.value.tenantId; importTenant.value = tenantId; importProduct.value = firstProduct(tenantId); importRows.value = []; importPreview.value = null; importError.value = ''; importing.value = true; }
function setImportTenant(tenantId: string) { importTenant.value = tenantId; importProduct.value = firstProduct(tenantId); importRows.value = []; importPreview.value = null; }
async function readImport(file?: File) { importRows.value = []; importPreview.value = null; importError.value = ''; if (!file) return; try { const parsed = parseDeviceCsv(await file.text(), importTenant.value, importProduct.value); if ('error' in parsed) { importError.value = parsed.error; return; } const result = await devices.previewImport(context(), parsed.rows); if ('error' in result) { importError.value = result.error.message; return; } importRows.value = parsed.rows; importPreview.value = result.data; } catch { importError.value = 'CSV 文件读取失败'; } }
async function commitImport() { const rows = JSON.parse(JSON.stringify(importRows.value)) as DeviceInput[]; const result = await devices.importBatch(context(), rows, true); if ('error' in result) { importError.value = result.error.message; importPreview.value = null; return; } importing.value = false; selectedRows.value = []; reload.value++; message.value = `已导入 ${result.data.length} 台未激活设备`; }
async function confirmDelete() { const result = await devices.deleteBatch(context(), [...deletePending.value], true); if ('error' in result) { deleteError.value = result.error.message; return; } deletePending.value = []; selectedRows.value = []; if (detail.value && result.data.deleted.includes(detail.value.id)) { selected.value = null; detail.value = null; live.value = false; } reload.value++; message.value = `已删除 ${result.data.deleted.length} 台设备；历史记录保留`; }
async function submitCommand() { if (!detail.value || !chosenCapability.value) return; const result = await devices.executeCommand(context(), detail.value.id, chosenCapability.value.id, parsedCommandValue.value); if ('error' in result) { commandError.value = result.error.message + (result.error.fieldErrors?.value ? `：${result.error.fieldErrors.value}` : ''); return; } commandError.value = ''; commandPreview.value = false; tab.value = 'commands'; history.value = [result.data, ...history.value]; }
function chooseMetric(id: string, checked: boolean) { metrics.value = checked ? [...metrics.value, id] : metrics.value.filter(item => item !== id); }
function focusTelemetryRange() { document.querySelector<HTMLSelectElement>('select[aria-label="时序范围"]')?.focus(); }
function chartPoints(metric: string) { return visiblePoints.value.filter(point => point.metric === metric); }
function chartSegments(metric: string) { const points = chartPoints(metric); const values = points.filter(point => point.value !== null).map(point => point.value as number); if (!values.length) return []; const min = Math.min(...values), max = Math.max(...values), spread = Math.max(1, max - min); const segments: string[] = []; let path = ''; points.forEach((point, index) => { if (point.value === null) { if (path) segments.push(path); path = ''; } else path += `${path ? ' L' : 'M'} ${(32 + index * 648 / Math.max(1, points.length - 1)).toFixed(1)} ${(150 - (point.value - min) / spread * 116).toFixed(1)}`; }); if (path) segments.push(path); return segments; }
function chartDots(metric: string) { const points = chartPoints(metric); const values = points.filter(point => point.value !== null).map(point => point.value as number); if (!values.length) return []; const min = Math.min(...values), spread = Math.max(1, Math.max(...values) - min); return points.flatMap((point, index) => point.value === null ? [] : [{ timestamp: point.timestamp, x: 32 + index * 648 / Math.max(1, points.length - 1), y: 150 - (point.value - min) / spread * 116, label: `${point.timestamp}：${point.value} ${point.unit}` }]); }
</script>

<template>
  <div class="atlas-dashboard atlas-devices"><aside class="atlas-sidebar" aria-label="主导航"><div class="atlas-brand">IoT <strong>Atlas</strong></div><nav><a href="/dashboard">◇ 数据大盘</a><a href="/geography">◇ 全球节点</a><a href="/products">▣ 产品与物模型</a><a class="active" aria-current="page" href="/devices">▣ 设备中心</a><a href="/rules">◇ 规则引擎</a><a href="/firmware">◇ 固件与 OTA</a><a href="/tenants">◇ 租户管理</a><a href="/labs">◇ 实验室</a><a href="/delivery">◇ 交付看板</a></nav><a class="diagnostic-link" href="/">诊断页</a></aside>
    <main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 设备中心</small><h1>设备中心</h1><p>查看设备状态、时序数据与模拟控制。</p></div><div class="header-actions"><label>主题<select v-model="themeChoice" aria-label="主题"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>演示身份<select :value="role" aria-label="演示身份" @change="changeRole(($event.target as HTMLSelectElement).value as Role)"><option value="platformAdmin">平台管理员</option><option value="tenantAdmin">租户管理员</option><option value="operator">运维工程师</option><option value="viewer">数据观察员</option></select></label></div></header>
    <ElCard class="device-filters"><div class="device-filter-grid"><label>搜索<input v-model="draft.keyword" aria-label="搜索设备" placeholder="设备 ID、名称或标签"></label><label>租户<select v-model="draft.tenantId" aria-label="设备租户" :disabled="role !== 'platformAdmin'"><option value="all">全部租户</option><option v-for="item in tenantNames" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>产品<select v-model="draft.productId" aria-label="设备产品"><option value="">全部产品</option><option v-for="(name, id) in productNames" :key="id" :value="id">{{ name }}</option></select></label><label>状态<select v-model="draft.status" aria-label="设备状态"><option value="">全部状态</option><option v-for="(name, id) in statuses" :key="id" :value="id">{{ name }}</option></select></label><label>地域<select v-model="draft.region" aria-label="设备地域"><option value="">全部地域</option><option v-for="(name, id) in regions" :key="id" :value="id">{{ name }}</option></select></label><label>标签<input v-model="draft.tag" aria-label="设备标签" placeholder="输入完整标签"></label><div class="device-filter-actions"><ElButton type="primary" @click="apply">查询</ElButton><ElButton @click="reset">重置</ElButton><ElButton v-if="role === 'platformAdmin' || role === 'tenantAdmin'" type="primary" @click="newDevice">新建设备</ElButton><ElButton v-if="role === 'platformAdmin' || role === 'tenantAdmin'" @click="openImport">CSV 导入</ElButton></div></div><details class="scenario-control"><summary>更多筛选与演示状态</summary><label>最后活跃（UTC）<input aria-label="最后活跃起始时间" type="datetime-local" :value="draft.lastActiveFrom?.slice(0, 16) ?? ''" @change="draft.lastActiveFrom = ($event.target as HTMLInputElement).value ? utcMinuteToIso(($event.target as HTMLInputElement).value) : undefined"></label><label>Mock 场景<select v-model="scenario" aria-label="Mock 场景"><option value="normal">正常</option><option value="slow">缓慢</option><option value="offline">服务离线</option><option value="forbidden">无权限</option></select></label></details><div class="device-filter-chips"><button v-for="[key, value] in chips" :key="key" @click="removeChip(key)">{{ key }}：{{ value }} ×</button></div></ElCard>
    <div class="dashboard-feedback" aria-live="polite"><span v-if="loading" role="status">设备加载中…</span><span v-if="message" role="alert">{{ message }} <button @click="reload++">重试</button></span></div>
    <ElCard class="device-list"><div class="product-list-head"><h2>设备列表 <small>共 {{ total }} 条</small></h2><details><summary>列设置</summary><label><input v-model="showRegion" type="checkbox"> 地域</label><label><input v-model="showLastActive" type="checkbox"> 最后活跃</label></details></div><div class="device-list-actions">已选 {{ selectedRows.length }} 项 <ElButton :disabled="!selectedRows.length" @click="exportRows">批量导出 CSV</ElButton><ElButton v-if="role === 'platformAdmin' || role === 'tenantAdmin'" :disabled="!selectedRows.length" @click="deleteError = ''; deletePending = [...selectedRows]">批量删除</ElButton></div><div class="product-table-wrap"><table><thead><tr><th><input aria-label="选择当前页设备" type="checkbox" :checked="rows.length > 0 && rows.every(item => selectedRows.includes(item.id))" @change="selectPage(($event.target as HTMLInputElement).checked)"></th><th><button @click="sort('name')">设备名称 ↕</button></th><th>设备 ID</th><th>产品</th><th><button @click="sort('status')">状态 ↕</button></th><th v-if="showRegion">地域</th><th v-if="showLastActive"><button @click="sort('lastActiveAt')">最后活跃 ↕</button></th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><input :aria-label="`选择 ${item.name}`" type="checkbox" :checked="selectedRows.includes(item.id)" @change="selectRow(item.id, ($event.target as HTMLInputElement).checked)"></td><td><button @click="selected = item.id">{{ item.name }}</button></td><td>{{ item.id }}</td><td>{{ productNames[item.productId] }}</td><td><span class="device-status" :class="item.status">{{ statuses[item.status] }}</span></td><td v-if="showRegion">{{ regions[item.region] }}</td><td v-if="showLastActive">{{ item.lastActiveAt ? new Date(item.lastActiveAt).toLocaleString('zh-CN') : '从未活跃' }}</td></tr></tbody></table><p v-if="!loading && !rows.length">当前筛选没有设备。可重置条件后重试。</p></div><div class="product-pager"><label>每页<select aria-label="每页条数" :value="query.pageSize" @change="query = { ...query, page: 1, pageSize: Number(($event.target as HTMLSelectElement).value) }; draft = { ...query }"><option value="2">2</option><option value="10">10</option><option value="20">20</option></select></label><ElButton :disabled="query.page <= 1" @click="query = { ...query, page: query.page - 1 }">上一页</ElButton><span>{{ query.page }} / {{ Math.max(1, Math.ceil(total / query.pageSize)) }}</span><ElButton :disabled="query.page * query.pageSize >= total" @click="query = { ...query, page: query.page + 1 }">下一页</ElButton></div></ElCard></main>
    <aside v-if="selected" class="product-drawer device-drawer" role="dialog" aria-modal="false" aria-label="设备详情"><div class="drawer-head"><div><h2>{{ detail?.name ?? '设备加载中' }}</h2><p>{{ detail?.id }} · {{ detail && productNames[detail.productId] }} · <span v-if="detail" class="device-status" :class="detail.status">{{ statuses[detail.status] }}</span></p></div><button aria-label="关闭设备详情" @click="selected = null; detail = null; live = false; commandPreview = false">×</button></div><template v-if="detail"><div class="product-tabs" role="tablist" aria-label="设备详情页签"><button v-for="(name, id) in tabNames" :key="id" role="tab" :aria-selected="tab === id" @click="tab = id">{{ name }}</button></div>
      <div v-if="tab === 'overview'" role="tabpanel"><h3>设备信息</h3><dl class="device-facts"><dt>产品</dt><dd>{{ productNames[detail.productId] }}</dd><dt>地域</dt><dd>{{ regions[detail.region] }} · {{ detail.countryCode }}</dd><dt>最后活跃</dt><dd>{{ detail.lastActiveAt ?? '从未活跃' }}</dd><dt>标签</dt><dd>{{ detail.tags.join('、') }}</dd><dt>信号</dt><dd>{{ detail.signalDbm ?? '—' }} dBm</dd></dl><div v-if="role === 'platformAdmin' || role === 'tenantAdmin'" class="device-edit"><h3>编辑元数据</h3><label>设备名称<input v-model="nameDraft" aria-label="编辑设备名称"></label><label>标签（逗号分隔）<input v-model="tagsDraft" aria-label="编辑设备标签"></label><ElButton type="primary" @click="saveMetadata">保存设备信息</ElButton></div></div>
      <div v-if="tab === 'realtime'" role="tabpanel"><h3>实时属性</h3><p v-if="detail.status !== 'online'" role="status">设备不在线，数据可能过期。</p><table><thead><tr><th>指标</th><th>当前值</th><th>最后更新</th></tr></thead><tbody><tr v-for="(value, key) in detail.attributes" :key="key"><td>{{ key }}</td><td>{{ value }}</td><td>{{ detail.lastActiveAt ?? '无数据' }}</td></tr></tbody></table><h3>模拟控制</h3><div v-if="capabilities.length" class="device-control"><label>命令<select v-model="commandItem" aria-label="控制命令" @change="commandValue = ''; commandPreview = false"><option value="">选择命令</option><option v-for="item in capabilities" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>参数<select v-if="chosenCapability?.dataType === 'bool'" v-model="commandValue" aria-label="控制参数"><option value="">请选择</option><option value="true">是</option><option value="false">否</option></select><input v-else v-model="commandValue" aria-label="控制参数" :type="chosenCapability?.dataType === 'int' || chosenCapability?.dataType === 'float' ? 'number' : 'text'"></label><p v-if="chosenCapability">模型约束：{{ chosenCapability.dataType }} {{ chosenCapability.unit ?? '' }} {{ chosenCapability.min !== undefined ? `${chosenCapability.min}–${chosenCapability.max}` : '' }}</p><ElButton type="primary" :disabled="role === 'viewer' || detail.status !== 'online' || !chosenCapability || commandValue === ''" @click="commandError = ''; commandPreview = true">预览命令</ElButton><p v-if="role === 'viewer'">观察员无控制权限。</p><p v-if="detail.status !== 'online'">设备离线或不可控制，控制已禁用。</p><p v-if="commandError" role="alert">{{ commandError }}</p></div><p v-else>当前产品没有可写模型项。</p></div>
      <div v-if="tab === 'shadow'" role="tabpanel"><h3>设备影子</h3><p>已上报值来自本端设备属性；期望值仅表示待执行的可写属性命令。</p><p v-if="shadowError" role="alert">{{ shadowError }}</p><template v-if="shadow"><p>设备最后活跃：{{ shadow.lastActiveAt ?? '无数据' }}</p><div class="device-telemetry-table"><table><thead><tr><th>属性</th><th>已上报值</th><th>期望值</th><th>待执行命令</th></tr></thead><tbody><tr v-for="item in shadow.entries" :key="item.identifier"><td>{{ item.identifier }}</td><td>{{ String(item.reported) }}</td><td>{{ item.desired === null ? '—' : String(item.desired) }}</td><td>{{ item.desiredCommandId ?? '—' }}</td></tr></tbody></table></div><p v-if="!shadow.entries.length">该设备尚无上报属性。</p></template></div>
      <div v-if="tab === 'telemetry'" role="tabpanel"><h3>时序分析</h3><div class="device-telemetry-controls"><fieldset><legend>指标</legend><label v-for="id in Object.keys(detail.attributes)" :key="id"><input type="checkbox" :checked="metrics.includes(id)" @change="chooseMetric(id, ($event.target as HTMLInputElement).checked)"> {{ id }}</label></fieldset><label>时间范围<select v-model.number="range" aria-label="时序范围"><option :value="1">最近 24 小时</option><option :value="7">最近 7 天</option><option :value="30">最近 30 天</option><option :value="0">自定义 UTC</option></select></label><template v-if="range === 0"><label>开始时间（UTC）<input v-model="customFrom" type="datetime-local" aria-label="开始时间（UTC）"></label><label>结束时间（UTC）<input v-model="customTo" type="datetime-local" aria-label="结束时间（UTC）"></label></template><label>采样粒度<select v-model="granularity" aria-label="采样粒度"><option value="minute">1 分钟</option><option value="hour">1 小时</option><option value="day">1 天</option></select></label><label><input v-model="live" type="checkbox"> 实时追加</label><ElButton @click="zoom = !zoom">{{ zoom ? '恢复全范围' : '放大后半段' }}</ElButton><ElButton :disabled="!telemetry" @click="exportTelemetry">导出 CSV</ElButton></div><p v-if="telemetryError" role="alert">{{ telemetryError }}。可调整范围或粒度后重试。</p><p v-if="!metrics.length">请选择至少一个指标。</p><template v-if="telemetry"><p v-if="telemetry.noData" role="status">所选范围 {{ telemetry.points[0]?.timestamp }} 至 {{ telemetry.points[telemetry.points.length - 1]?.timestamp }}（UTC）无遥测数据；<button type="button" @click="focusTelemetryRange">调整时间范围</button>或采样粒度。</p><p v-if="telemetry.missing.length" role="status">存在 {{ telemetry.missing.length }} 个缺失采样时段，曲线在缺点处断开。</p><div v-for="metric in (telemetry.noData ? [] : telemetry.metrics)" :key="metric.id" class="device-chart"><strong>{{ metric.id }}（{{ metric.unit || '无单位' }}）</strong><svg viewBox="0 0 720 185" role="img" :aria-label="`${metric.id} 时序曲线，${chartPoints(metric.id).length} 个采样点`"><line x1="32" y1="150" x2="680" y2="150" stroke="currentColor" opacity="0.45" /><path v-for="(path, index) in chartSegments(metric.id)" :key="index" :d="path" fill="none" stroke="#36d8eb" stroke-width="2.5" /><circle v-for="dot in chartDots(metric.id)" :key="dot.timestamp" :cx="dot.x" :cy="dot.y" r="4" fill="#36d8eb"><title>{{ dot.label }}</title></circle></svg></div><details><summary>数值摘要表（可复制）</summary><div class="device-telemetry-table"><table><thead><tr><th>时间</th><th>指标</th><th>值</th><th>单位</th><th>质量</th></tr></thead><tbody><tr v-for="point in visiblePoints" :key="`${point.timestamp}:${point.metric}`"><td>{{ point.timestamp }}</td><td>{{ point.metric }}</td><td>{{ point.value ?? '缺失' }}</td><td>{{ point.unit }}</td><td>{{ point.quality }}</td></tr></tbody></table></div></details></template></div>
      <div v-if="tab === 'messages'" role="tabpanel"><h3>原始消息</h3><p v-if="eventError" role="alert">{{ eventError }}</p><details v-for="item in rawMessages" :key="item.id"><summary>{{ item.occurredAt }} · 属性上报 · {{ item.id }}</summary><pre>{{ JSON.stringify(item.payload, null, 2) }}</pre></details><p v-if="!rawMessages.length && !eventError">当前设备没有原始消息。</p></div>
      <div v-if="tab === 'alarms'" role="tabpanel"><h3>告警</h3><p v-if="eventError" role="alert">{{ eventError }}</p><div v-for="item in alarms" :key="item.id" class="device-alarm"><strong>{{ item.description }}</strong><p>{{ item.occurredAt }} · {{ item.severity === 'critical' ? '严重' : item.severity === 'major' ? '重要' : '警告' }} · {{ item.status === 'open' ? '待确认' : `已由 ${item.acknowledgedBy} 确认` }}</p><ElButton v-if="item.status === 'open'" :disabled="role === 'viewer'" @click="acknowledgeAlarm(item.id)">确认告警</ElButton></div><p v-if="!alarms.length && !eventError">当前设备没有告警。</p></div>
      <div v-if="tab === 'location'" role="tabpanel"><h3>位置</h3><p v-if="detail.location">{{ detail.countryCode }} · 演示级城市坐标 {{ detail.location[1].toFixed(2) }}, {{ detail.location[0].toFixed(2) }}</p><p v-else>该设备没有可用坐标，列入未定位设备。</p><a href="/geography">查看全球节点</a></div>
      <div v-if="tab === 'rules'" role="tabpanel"><h3>规则执行</h3><p v-if="ruleLogError" role="alert">{{ ruleLogError }}</p><details v-for="item in ruleLogs" :key="item.id"><summary>{{ item.ruleId }} · {{ item.status }} · {{ new Date(item.occurredAt).toLocaleString('zh-CN') }}</summary><p>{{ item.mode === 'applied' ? '已确认应用模拟结果' : '模拟事件' }} · {{ item.alarmCreated ? '已生成模拟告警' : '无模拟告警' }}</p><ol><li v-for="trace in item.traces" :key="trace.nodeId">{{ trace.nodeId }} · {{ trace.status }} · {{ trace.durationMs }} ms {{ trace.reason ?? '' }}</li></ol></details><p v-if="!ruleLogs.length && !ruleLogError">当前设备没有演示规则执行记录。</p><a href="/rules">查看规则引擎</a></div>
      <div v-if="tab === 'ota'" role="tabpanel"><h3>OTA 历史</h3><p v-if="otaError" role="alert">{{ otaError }}</p><details v-for="item in otaHistory" :key="item.execution.id"><summary>{{ item.taskId }} · 第 {{ item.execution.attempt }} 次尝试 · {{ item.execution.status }}</summary><p>{{ item.execution.fromVersion }} → {{ item.execution.toVersion }} · 第 {{ item.execution.batch + 1 }} 批 · {{ item.execution.reason ?? '模拟执行记录' }}</p><a :href="`/firmware?tab=ota&task=${encodeURIComponent(item.taskId)}`">查看 OTA 任务</a></details><p v-if="!otaHistory.length && !otaError">当前设备没有演示 OTA 执行记录。</p><a href="/firmware?tab=ota">查看 OTA 任务列表</a></div>
      <div v-if="tab === 'commands'" role="tabpanel"><h3>命令记录</h3><table><thead><tr><th>命令</th><th>参数</th><th>状态</th><th>结果</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td>{{ item.identifier }}</td><td>{{ item.value }}</td><td>{{ item.status === 'pending' ? '执行中' : item.status === 'succeeded' ? '成功' : '失败' }}</td><td>{{ item.reason ?? (item.status === 'pending' ? '等待设备响应' : '模拟执行完成') }}</td></tr></tbody></table><p v-if="!history.length">暂无命令记录。</p></div>
    </template></aside>
    <div v-if="creating" class="product-modal-backdrop"><div class="product-modal device-entry-dialog" role="dialog" aria-modal="true" aria-label="新建设备" tabindex="-1"><h2>新建设备</h2><p role="status">{{ capacityNote }}</p><div class="device-create-form"><label>目标租户<select aria-label="新建设备租户" :value="createInput.tenantId" :disabled="role !== 'platformAdmin'" @change="setCreateTenant(($event.target as HTMLSelectElement).value)"><option v-for="item in tenantNames" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>所属产品<select aria-label="新建设备产品" v-model="createInput.productId"><option v-for="(name, id) in productNames" v-show="publishedProducts.some(item => item.id === id && item.tenantId === createInput.tenantId)" :key="id" :value="id">{{ name }}</option></select></label><label>设备名称<input aria-label="新设备名称" v-model="createInput.name"></label><label>地域<select aria-label="新设备地域" v-model="createInput.region"><option v-for="(name, id) in regions" :key="id" :value="id">{{ name }}</option></select></label><label>国家代码<input aria-label="新设备国家代码" maxlength="2" :value="createInput.countryCode" @input="createInput.countryCode = ($event.target as HTMLInputElement).value.toUpperCase()"></label><label>标签（逗号分隔）<input aria-label="新设备标签" :value="createInput.tags.join(',')" @input="createInput.tags = ($event.target as HTMLInputElement).value.split(',').map(item => item.trim()).filter(Boolean)"></label></div><p v-if="createError" role="alert">{{ createError }}</p><div class="device-create-actions"><ElButton type="primary" @click="createDevice">确认登记</ElButton><ElButton @click="creating = false">取消</ElButton></div></div></div>
    <div v-if="importing" class="product-modal-backdrop"><div class="product-modal device-entry-dialog" role="dialog" aria-modal="true" aria-label="CSV 导入设备" tabindex="-1"><h2>CSV 导入设备</h2><p>表头：name,region,countryCode,tags；多个标签用 | 分隔。一次最多 100 台，全部通过校验后才会写入。</p><div class="device-create-form"><label>导入租户<select aria-label="导入租户" :value="importTenant" :disabled="role !== 'platformAdmin'" @change="setImportTenant(($event.target as HTMLSelectElement).value)"><option v-for="item in tenantNames" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>导入产品<select aria-label="导入产品" v-model="importProduct" @change="importRows = []; importPreview = null"><option v-for="item in publishedProducts.filter(item => item.tenantId === importTenant)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>CSV 文件<input aria-label="导入 CSV 文件" type="file" accept=".csv,text/csv" @change="readImport(($event.target as HTMLInputElement).files?.[0])"></label></div><p v-if="importError" role="alert">{{ importError }}</p><div v-if="importPreview" role="status"><p>预览：{{ importPreview.count }} 台未激活设备；{{ importPreview.tenants.map(item => `${item.tenantId} ${item.before}→${item.after}`).join('，') }}</p><p>{{ importPreview.names.join('、') }}</p></div><div class="device-create-actions"><ElButton type="primary" :disabled="!importPreview" @click="commitImport">确认导入</ElButton><ElButton @click="importing = false">取消</ElButton></div></div></div>
    <div v-if="deletePending.length" class="product-modal-backdrop"><div class="product-modal device-entry-dialog" role="dialog" aria-modal="true" aria-label="确认删除设备" tabindex="-1"><h2>确认删除 {{ deletePending.length }} 台设备</h2><p>将从本端设备列表移除所选设备；已有规则和 OTA 历史记录保留。</p><p>{{ deletePending.join('、') }}</p><p v-if="deleteError" role="alert">{{ deleteError }}</p><div class="device-create-actions"><ElButton type="primary" @click="confirmDelete">确认删除</ElButton><ElButton @click="deletePending = []">取消</ElButton></div></div></div>
    <div v-if="commandPreview && detail && chosenCapability" class="product-modal-backdrop device-control-backdrop"><div class="product-modal device-control-sheet" role="dialog" aria-modal="true" aria-label="控制预览" tabindex="-1"><h2>确认控制命令</h2><p>目标：{{ detail.name }}（{{ detail.id }}）</p><p>命令：{{ chosenCapability.name }} · 参数：{{ parsedCommandValue }} {{ chosenCapability.unit ?? '' }}</p><p>权限：{{ role === 'viewer' ? '无权控制' : '可控制' }} · 设备：{{ statuses[detail.status] }}</p><p v-if="commandError" role="alert">{{ commandError }}</p><div><ElButton type="primary" @click="submitCommand">发送命令</ElButton><ElButton @click="commandPreview = false">取消</ElButton></div></div></div>
  </div>
</template>
